param(
  [string]$AppDir = 'C:\rike',
  [int]$Port = 8788,
  [switch]$NoTask
)

# 日课 · 学习自律与每日时间统计 —— 服务器安装包
# 版本 0.2.12    生成于 2026-10-26 10:33
# 用法：管理员 PowerShell 里执行本脚本即可。重复执行=升级（数据在 $AppDir\data，不会被覆盖）
# 调试： deploy 目录下可以 -AppDir D:\rike-test -Port 8799 -NoTask
$ErrorActionPreference = 'Stop'
$ZipPath = Join-Path $env:TEMP 'rike-install.zip'

function Say($m) { Write-Host ""; Write-Host "== $m" -ForegroundColor Cyan }
function OK($m) { Write-Host "   [OK] $m" -ForegroundColor Green }
function Warn($m) { Write-Host "   [!] $m" -ForegroundColor Yellow }
function Fail($m) { Write-Host "   [X] $m" -ForegroundColor Red; exit 1 }

Write-Host "日课 安装/升级  版本 0.2.12" -ForegroundColor Cyan
Write-Host "目标目录 $AppDir   端口 $Port"

# ---------------------------------------------------------------- 0. 管理员
$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole(
  [Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $isAdmin) {
  if ($NoTask) { Warn "不是管理员，跳过计划任务和防火墙（-NoTask）" }
  else { Fail "请用管理员身份运行 PowerShell" }
}

# ---------------------------------------------------------------- 1. 找 Node
Say "找 Node.js"
$nodeBin = $null
foreach ($p in @(
    "$env:ProgramFiles\nodejs\node.exe",
    "${env:ProgramFiles(x86)}\nodejs\node.exe",
    "C:\beisong\node\node.exe",
    "C:\nodejs\node.exe")) {
  if (Test-Path $p) { $nodeBin = $p; break }
}
if (-not $nodeBin) {
  $cmd = Get-Command node.exe -ErrorAction SilentlyContinue
  if ($cmd) { $nodeBin = $cmd.Source }
}
if (-not $nodeBin) { Fail "没找到 node.exe。先装 Node 22+（或把便携版放到 C:\beisong\node\node.exe）" }
$nodeVer = (& $nodeBin -v) -join ''
OK "Node $nodeVer  ($nodeBin)"

# ---------------------------------------------------------------- 2. 解包
Say "解包到 $AppDir"
$b64 = @'










































































































'@
[IO.File]::WriteAllBytes($ZipPath, [Convert]::FromBase64String($b64))
New-Item -ItemType Directory -Force -Path $AppDir | Out-Null
# 保留 data 目录（升级时不动数据）
Expand-Archive -Path $ZipPath -DestinationPath $AppDir -Force
Remove-Item $ZipPath -Force -ErrorAction SilentlyContinue
if (-not (Test-Path "$AppDir\server\server.js")) { Fail "解包后找不到 server\server.js" }
OK "代码就位"

# ---------------------------------------------------------------- 3. 清理旧实例
Say "停掉正在跑的旧实例"
# 只杀「命令行里带本次安装目录下 server.js」的进程。
# 不能用模糊匹配（比如 *rike*），否则同机别的 Node 应用可能被误杀 —— 背诵系统就在旁边跑着。
# 而且要先停计划任务：启动脚本里有个重启循环，光杀 node 的话 3 秒后它又起来了。
Stop-ScheduledTask -TaskName 'rike' -ErrorAction SilentlyContinue
Start-Sleep -Milliseconds 500
$targetJs = Join-Path $AppDir 'server\server.js'
$targetCmd = Join-Path $AppDir 'service-run.cmd'
foreach ($pat in @($targetJs, $targetCmd)) {
  Get-CimInstance Win32_Process -ErrorAction SilentlyContinue |
    Where-Object { $_.CommandLine -and $_.CommandLine.IndexOf($pat, [StringComparison]::OrdinalIgnoreCase) -ge 0 } |
    ForEach-Object {
      Warn "  停掉 PID $($_.ProcessId) $($_.Name)"
      Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue
    }
}
Start-Sleep -Seconds 1
OK "已清理（只影响 $targetJs 和它的启动脚本）"

# ---------------------------------------------------------------- 4. 启动包装脚本
# 注意：不要用 sc.exe 注册服务。node.exe 是普通控制台程序，不实现 SCM 协议，
# 服务管理器会等 30 秒后报「错误 1053」并杀掉进程。计划任务没有这个问题。
Say "写启动脚本"
$wrapper = Join-Path $AppDir 'service-run.cmd'
@"
@echo off
set RIKE_DATA_DIR=$AppDir\data
set RIKE_PORT=$Port
set RIKE_HOST=0.0.0.0
set RIKE_DEPLOY_PUB=MCowBQYDK2VwAyEARjI1cpDRTFJPDK52ZfCI64qtoUeTq+1RpppyHdP327k=
:loop
"$nodeBin" "$AppDir\server\server.js" --port=$Port --data="$AppDir\data" >> "$AppDir\service.log" 2>&1
rem 进程被外部杀掉（比如同机另一个应用升级时误杀）也在这里活过来
echo [%date% %time%] 进程退出，3 秒后重启 >> "$AppDir\service.log"
ping -n 4 127.0.0.1 >nul
goto loop
"@ | Set-Content -Path $wrapper -Encoding ASCII
OK $wrapper

# ---------------------------------------------------------------- 5. 计划任务
if ($NoTask) {
  Say "跳过计划任务（-NoTask），直接后台启动"
  Start-Process -FilePath $wrapper -WindowStyle Hidden
  Start-Sleep -Seconds 3
} else {
Say "注册开机自启（计划任务）"
$taskName = 'rike'
try {
  Unregister-ScheduledTask -TaskName $taskName -Confirm:$false -ErrorAction SilentlyContinue
  $action = New-ScheduledTaskAction -Execute $wrapper -WorkingDirectory $AppDir
  $trigger = New-ScheduledTaskTrigger -AtStartup
  $settings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries `
      -RestartCount 999 -RestartInterval (New-TimeSpan -Minutes 1) `
      -ExecutionTimeLimit ([TimeSpan]::Zero) -MultipleInstances IgnoreNew
  $principal = New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest
  Register-ScheduledTask -TaskName $taskName -Action $action -Trigger $trigger `
      -Settings $settings -Principal $principal -Force `
      -Description '日课（Node.js）' -ErrorAction Stop | Out-Null
  Start-ScheduledTask -TaskName $taskName
  Start-Sleep -Seconds 4
  OK "计划任务 rike 已注册（开机自启，崩溃自动重试）"
} catch {
  Warn "计划任务注册失败：$($_.Exception.Message)"
  Say "改用后台进程启动"
  Start-Process -FilePath $wrapper -WindowStyle Hidden
  Start-Sleep -Seconds 2
}
}

# ---------------------------------------------------------------- 6. 防火墙
if ($NoTask) {
  Say "跳过防火墙（-NoTask）"
} else {
Say "放行防火墙 $Port"
$rule = Get-NetFirewallRule -DisplayName '日课' -ErrorAction SilentlyContinue
if ($rule) {
  OK "防火墙规则已存在"
} else {
  New-NetFirewallRule -DisplayName '日课' -Direction Inbound -LocalPort $Port -Protocol TCP -Action Allow | Out-Null
  OK "已放行 TCP $Port"
}
}

# ---------------------------------------------------------------- 7. 自检
Say "自检"
$ok = $false
for ($i = 0; $i -lt 20; $i++) {
  try {
    $h = Invoke-RestMethod "http://127.0.0.1:$Port/api/health" -TimeoutSec 3
    if ($h.ok) { $ok = $true; break }
  } catch { Start-Sleep -Milliseconds 800 }
}
if (-not $ok) {
  Warn "健康检查没通过，最后 20 行日志："
  if (Test-Path "$AppDir\service.log") { Get-Content "$AppDir\service.log" -Tail 20 } else { Warn "没有 service.log" }
} else {
  OK "服务在跑：日课 v$($h.version)，已用 $($h.users) 个账号"
}

Write-Host ""
Write-Host "------------------------------------------------------------" -ForegroundColor DarkGray
if ($ok) { Write-Host " 安装完成" -ForegroundColor Green }
else { Write-Host " 代码已装好，但服务没起来 —— 先看上面的日志" -ForegroundColor Yellow }
Write-Host " 1) 阿里云安全组放行入方向 TCP $Port（访问来源 0.0.0.0/0）" -ForegroundColor Gray
Write-Host " 2) 浏览器打开 http://<公网IP>:$Port ，第一次会引导创建账号" -ForegroundColor Gray
Write-Host " 3) 之后注册会自动关闭，只有第一个账号是主人" -ForegroundColor Gray
Write-Host " 数据目录：$AppDir\data    日志：$AppDir\service.log" -ForegroundColor DarkGray
Write-Host "------------------------------------------------------------" -ForegroundColor DarkGray
